 s public.hb_policy_sources%rowtype;
 p public.hb_policy_versions%rowtype;
 w public.hb_workflow_templates%rowtype;
 new_steps jsonb;
 pv integer;
 wv integer;
 required_count integer;
 reviewed timestamptz := '2026-10-10T05:32:40Z';
begin
 for r in select value from jsonb_array_elements($reviews$[{"slug":"abu-dhabi-economic-initial-approval-guide","sourceId":"f3cc66df-6efe-4749-8d0d-2e8db6df4498","authority":"added-abu-dhabi","url":"https://added.gov.ae/en/set-up/establish-your-business","requirementCount":4,"rules":[{"id":"requirement:1","when":[],"effect":"review","reason":"تحديد النشاط التجاري","actions":["collect_or_verify_requirement"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"requirement:2","when":[],"effect":"review","reason":"اختيار الشكل القانوني","actions":["collect_or_verify_requirement"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"requirement:3","when":[],"effect":"review","reason":"تسجيل الاسم التجاري","actions":["collect_or_verify_requirement"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"requirement:4","when":[],"effect":"review","reason":"الموافقات الإضافية للأنشطة المنظمة عند انطباقها","actions":["collect_or_verify_requirement"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"conditions","when":[],"effect":"review","reason":"هذا دليل لرحلة التأسيس والموافقة المبدئية؛ العقود والموقع والموافقات تعتمد على النشاط والشكل القانوني. الرابط لا يرسل طلب تنفيذ.","actions":["review_conditions"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"fees","when":[],"effect":"review","reason":"لا ينشر هذا الدليل رسمًا ثابتًا لهذه الحالة؛ تؤكد الرسوم النهائية داخل خدمة TAMM المختارة.","actions":["review_fees"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]},{"id":"duration","when":[],"effect":"review","reason":"لا يقدم الدليل مدة ملزمة لكل حالة؛ تحقق من مدة الخدمة والموافقات داخل المعاملة المختارة.","actions":["review_duration"],"sourceRefs":["https://added.gov.ae/en/set-up/establish-your-business"]}]},{"slug":"abu-dhabi-economic-license-mortgage-guide","sourceId":"dc8f32cf-0f07-4b2f-8ce1-6fe05acfe9ae","author