y_requirement"],"sourceRefs":["https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements"]},{"id":"conditions","when":[],"effect":"review","reason":"يذكر دليل ADDED هذه المعاملة ضمن خدمات الترخيص. الرابط للإرشاد؛ تؤكد شروط الحالة والمستندات في خدمة TAMM المطابقة.","actions":["review_conditions"],"sourceRefs":["https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements"]},{"id":"fees","when":[],"effect":"review","reason":"لا ينشر هذا الدليل رسمًا ثابتًا لهذه الحالة؛ تؤكد الرسوم النهائية داخل خدمة TAMM المختارة.","actions":["review_fees"],"sourceRefs":["https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements"]},{"id":"duration","when":[],"effect":"review","reason":"لا يقدم الدليل مدة ملزمة لكل حالة؛ تحقق من مدة الخدمة والموافقات داخل المعاملة المختارة.","actions":["review_duration"],"sourceRefs":["https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements"]}]},{"slug":"sharjah-business-licensing-guide","sourceId":"aa06f3db-c703-429c-9db3-ce00994bb43f","authority":"sharjah-ded","url":"https://sedd.ae/en/home","requirementCount":4,"rules":[{"id":"requirement:1","when":[],"effect":"review","reason":"الدليل لا يقدم قائمة مستندات موحدة لكل معاملات الترخيص.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"requirement:2","when":[],"effect":"review","reason":"اختر مسار بدء النشاط أو استمرار العمل أو التعديل أو الإغلاق.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"requirement:3","when":[],"effect":"review","reason":"استخدم أداتي النشاط والاسم التجاري للاستعداد قبل اختيار الخدمة.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"requirement:4","when":[],"effect":"review","reason":"أكد المستندات والموافقات من بطاقة الخدمة المطابقة لحالتك.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"conditions","when":[],"effect":"review","reason":"هذا دليل SEDD لاختيار المسار، وليس بطاقة تنفيذ واحدة؛ تختلف المتطلبات بحسب الخدمة والنشاط والحالة.","actions":["review_conditions"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"fees","when":[],"effect":"review","reason":"لا ينشر هذا الدليل إجماليًا موحدًا؛ الحاسبة للتقدير وتؤكد الخدمة المختارة الرسوم النهائية.","actions":["review_fees"],"sourceRefs":["https://sedd.ae/en/home"]},{"id":"duration","when":[],"effect":"review","reason":"لا يقدم الدليل مدة ملزمة لكل حالة؛ تحقق من مدة الخدمة والموافقات داخل المعاملة المختارة.","actions":["review_duration"],"sourceRefs":["https://sedd.ae/en/home"]}]}]$reviews$::jsonb) loop
  select * into s from public.hb_policy_sources
   where id=(r->>'sourceId')::uuid and authority_key=r->>'authority'
    and source_url=r->>'url' and active for update;
  if not found then raise notice 'Guidance source absent: %',r->>'slug'; continue; end if;
  begin
   select v.* into strict p from public.hb_policy_versions v
    join public.hb_service_bindings b on b.policy_key=v.policy_key
    where b.service_slug=r->>'slug' and b.active and v.status='active' for update of v;
  exception when no_data_found then raise notice 'Guidance policy absent: %',r->>'slug'; continue; end;
  if not(s.id=any(p.source_ids)) then raise exception 'Guidance source binding mismatch: %',r->>'slug'; end if;
  if exists(select 1 from public.hb_policy_versions v where v.policy_key=p.policy_key
    and v.reviewed_by='official-guidance-review-2026-10-10' and v.rules=r->'rules') then continue; end if;
  begin
   select v.* into strict w from public.hb_workflow_templates v
    join public.hb_service_bindings b on b.workflow_key=v.workflow_key
    where b.service_slug=r->>'slug' and b.active and v.status='active' for update of v;
  exception when no_data_found then raise notice 'Guidance workflow absent: %',r->>'slug'; continue; end;
  select count(*) into required_count from jsonb_array_elements(w.definition->'steps') item where item->>'key' like 'requirement-%';
  if required_count<>(r->>'requirementCount')::integer then raise exception 'Guidance requirement count mismatch: %',r->>'slug'; end if;
  select coalesce(max(version),0)+1 into pv from public.hb_policy_versions where policy_key=p.policy_key and jurisdiction_id is not distinct from p.jurisdiction_id;
  select coalesce(max(version),0)+1 into wv from public.hb_workflow_templates where workflow_key=w.workflow_key and jurisdiction_id is not distinct from w.jurisdiction_id;
  select jsonb_agg(case
   when item->>'key' like 'requirement-%' then jsonb_set(item,'{title}',to_jsonb(r->'rules'->(split_part(item->>'key','-',2)::integer-1)->>'reason'))
   when item->>'key'='quality-review' then jsonb_set(item,'{metadata,conditions}',to_jsonb(r->'rules'->((r->>'requirementCount')::integer)->>'reason'))
   else item end order by ord) into new_steps
   from jsonb_array_elements(w.definition->'steps') with ordinality as steps(item,ord);
  update public.hb_policy_versions set status='retired',effective_until=reviewed where id=p.id;
  insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id)
   values(p.policy_key,p.jurisdiction_id,pv,reviewed,'active',r->'rules',p.source_ids,'official-guidance-review-2026-10-10',reviewed,p.country_pack_id);
  update public.hb_workflow_templates set status='retired',effective_until=reviewed where id=w.id;
  insert into public.hb_workflow_templates(workflow_key,jurisdiction_id,service_slug,version,status,definition,effective_from,country_pack_id)
   values(w.workflow_key,w.jurisdiction_id,w.service_slug,wv,'active',jsonb_set(jsonb_set(w.definition,'{steps}',new_steps),'{version}',to_jsonb(wv)),reviewed,w.country_pack_id);
  update public.hb_policy_sources set last_verified_at=reviewed,last_checked_at=reviewed,
   last_http_status=200,monitor_failures=0,monitor_error=null,review_required=false,
   metadata=metadata||jsonb_build_object('review_checkpoint','official-guidance-review-2026-10-10',
    'reverified_at',reviewed,'verification_state','OFFICIAL_GUIDANCE_VERIFIED',
    'verification_scope','guidance_identity_and_qualified_information_boundaries',
    'transaction_specific_checklist_complete',false,'final_fee_total_verified',false,
    'guaranteed_duration_verified',false,'review_source',r->>'url')
   where id=s.id;
 end loop;
end $guidance_review$;
commit;
